def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    P = 75

    opp_d = 0
    my_d = 0
    for i in range(n):
        if history[i][0] == 'D':
            my_d += 1
        if history[i][1] == 'D':
            opp_d += 1

    if opp_d == n:
        return 'D'

    if n < 3:
        return 'C'

    recent5 = 0
    s5 = n - 5
    if s5 < 0:
        s5 = 0
    for i in range(s5, n):
        if history[i][1] == 'D':
            recent5 += 1

    recent10 = 0
    s10 = n - 10
    if s10 < 0:
        s10 = 0
    for i in range(s10, n):
        if history[i][1] == 'D':
            recent10 += 1

    opp_streak_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak_d += 1
        else:
            break

    if n == P:
        if history[-1][0] == 'C' and history[-1][1] == 'C':
            if my_d <= 3 and opp_d <= 4 and recent5 == 0 and recent10 <= 1:
                return 'D'

    if n == P + 1:
        if history[P][0] == 'D' and history[P][1] == 'C':
            if my_d <= 4 and opp_d <= 5 and recent5 <= 1:
                return 'C'

    if n > P + 1:
        success = False
        if history[P][0] == 'D' and history[P + 1][0] == 'C' and history[P + 1][1] == 'C':
            punished = False
            for i in range(P + 1, n - 1):
                if history[i][0] == 'D' and history[i + 1][1] == 'D':
                    punished = True
                    break
            if not punished and recent5 == 0 and opp_d <= 5:
                success = True
        if success:
            return 'D'

    last_me, last_opp = history[-1]

    if last_opp == 'D':
        if (last_me == 'C' and n >= 2 and history[-2][0] == 'D' and
                opp_streak_d == 1 and recent5 <= 1 and opp_d <= 3):
            return 'C'
        if (last_me == 'D' and opp_streak_d == 1 and recent5 <= 1 and
                opp_d <= 3 and my_d <= 3):
            return 'C'
        return 'D'

    if opp_d >= max(3, n // 2) or recent10 >= 5:
        return 'D'

    return 'C'
